import json, pathlib, subprocess, tempfile, textwrap; repo = pathlib.Path.cwd();

def write_project(name, source):
    root = pathlib.Path(tempfile.mkdtemp(prefix=f'fozzylang-{name}-'))
    (root / 'src').mkdir(parents=True, exist_ok=True)
    (root / 'fozzy.toml').write_text(textwrap.dedent(f'''\
        [package]
        name="{name}"
        version="0.1.0"

        [[target.bin]]
        name="{name}"
        path="src/main.fzy"
    '''))
    (root / 'src/main.fzy').write_text(textwrap.dedent(source))
    return root

def verify(name, source, expect_rc):
    root = write_project(name, source)
    proc = subprocess.run(['cargo', 'run', '-q', '-p', 'fz', '--', 'verify', str(root), '--json'], cwd=str(repo), capture_output=True, text=True)
    payload = json.loads(proc.stdout.strip())
    assert proc.returncode == expect_rc, (name, proc.returncode, payload, proc.stderr)
    return payload

def messages(payload):
    return [item['message'] for item in payload['items']]

def find_message(payload, needle):
    return next(item for item in payload['items'] if needle in item['message'])

free_after_defer = verify('free_after_defer', '''
    fn main() -> i32 {
        let p = alloc(32)
        defer free(p)
        free(p)
        return 0
    }
''', 1)
assert any('consumes value `p` after scheduling deferred cleanup' in message for message in messages(free_after_defer)), free_after_defer

defer_after_free = verify('defer_after_free', '''
    fn main() -> i32 {
        let p = alloc(32)
        free(p)
        defer free(p)
        return 0
    }
''', 1)
assert any('schedules deferred cleanup for non-owned or already-consumed value `p`' in message or 'uses moved value `p` after move/consume' in message or 'uses value `p` after provenance root' in message for message in messages(defer_after_free)), defer_after_free

early_return_leak = verify('early_return_leak', '''
    fn main() -> i32 {
        let p = alloc(32)
        return 0
    }
''', 1)
assert any('leaks allocation' in message and '`p`' in message for message in messages(early_return_leak)), early_return_leak

branch_leak = verify('branch_leak', '''
    fn main() -> i32 {
        let p = alloc(32)
        if true {
            return 0
        }
        free(p)
        return 0
    }
''', 1)
assert any('leaks allocation' in message and '`p`' in message for message in messages(branch_leak)), branch_leak

loop_cleanup_gap = verify('loop_cleanup_gap', '''
    fn main() -> i32 {
        let p = alloc(32)
        while false {
            free(p)
        }
        return 0
    }
''', 1)
assert any('leaks allocation' in message or 'divergent ownership state for `p`' in message or 'conditionally consumed value `p`' in message for message in messages(loop_cleanup_gap)), loop_cleanup_gap

conditional_move = verify('conditional_move', '''
    fn main() -> i32 {
        let p = alloc(32)
        if true {
            let q = p
            discard q
        }
        free(p)
        return 0
    }
''', 1)
conditional_move_diag = find_message(conditional_move, 'uses conditionally consumed value `p` after path-sensitive ownership merge')
assert 'enforce ownership transfer semantics' in (conditional_move_diag.get('help') or ''), conditional_move_diag

partial_move_struct = verify('partial_move_struct', '''
    struct Pair { left: *mut u8, right: *mut u8 }
    fn main() -> i32 {
        let pair: Pair = Pair { left: alloc(32), right: alloc(32) }
        let Pair { left, right: _ } = pair
        free(left)
        return 0
    }
''', 1)
assert any('performs partial move from owned aggregate' in message for message in messages(partial_move_struct)), partial_move_struct

partial_move_enum = verify('partial_move_enum', '''
    enum Pairish { Both(*mut u8, *mut u8), Empty }
    fn main() -> i32 {
        let pair = Pairish::Both(alloc(32), alloc(32))
        match pair {
            Pairish::Both(left, _) => close(left),
            _ => return 0,
        }
        return 0
    }
''', 1)
assert any('performs partial move from owned aggregate' in message for message in messages(partial_move_enum)), partial_move_enum

mutable_shared_alias = verify('mutable_shared_alias', '''
    fn touch(a: &'a mut i32, b: &'a i32) -> i32 {
        return 0
    }
    fn main() -> i32 {
        let x: i32 = 1
        touch(x, x)
        return 0
    }
''', 1)
assert any('aliases mutable and shared borrows for `x`' in message for message in messages(mutable_shared_alias)), mutable_shared_alias

borrow_across_await = verify('borrow_across_await', '''
    use core.thread;
    async fn recv() -> Future<i32> {
        return 0
    }
    async fn worker(v: &'a i32) -> i32 {
        await recv()
        discard v
        return 0
    }
    fn main() -> i32 {
        return 0
    }
''', 1)
borrow_across_await_diag = find_message(borrow_across_await, 'cannot use borrowed reference `v` across await suspension points')
assert 'lifetime/region-safe ownership handoff' in (borrow_across_await_diag.get('help') or ''), borrow_across_await_diag

thread_borrowed_param = verify('thread_borrowed_param', '''
    use core.thread;
    async fn worker(v: &'a i32) -> i32 {
        discard v
        return 0
    }
    fn main() -> i32 {
        return 0
    }
''', 1)
thread_borrowed_param_diag = find_message(thread_borrowed_param, 'parameter `v` requires Send/Sync-safe wrapper before thread crossing')
assert 'wrap borrowed references/pointers' in (thread_borrowed_param_diag.get('help') or ''), thread_borrowed_param_diag

reference_return_mismatch = verify('reference_return_mismatch', '''
    fn borrow(v: &'b i32) -> &'b i32 {
        return v
    }
    fn relay(a: &'a i32, b: &'b i32) -> &'a i32 {
        return borrow(b)
    }
    fn main() -> i32 {
        return 0
    }
''', 1)
assert any('returns reference expression with mismatched lifetime' in message for message in messages(reference_return_mismatch)), reference_return_mismatch

print('compiler-memory-adversarial-ok')

